# --- FUNÇÕES DE PROCESSAMENTO ---

def processar_com_google(imagem_bytes, prompt_texto):
    try:
        response = client_google.models.generate_content(
            model="gemini-1.5-flash-latest",
            contents=[
                {"mime_type": "image/png", "data": imagem_bytes},
                prompt_texto
            ]
        )
        return response.text
    except Exception as e:
        return f"Erro na API Gemini: {e}"

def processar_com_anthropic(imagem_base64_string, prompt_texto):
    try:
        response = client_anthropic.messages.create(
            model="claude-3-5-sonnet-20240620",
            max_tokens=1024,
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": "image/png",
                                "data": imagem_base64_string,
                            },
                        },
                        {
                            "type": "text",
                            "text": prompt_texto
                        }
                    ],
                }
            ],
        )
        return response.content[0].text
    except Exception as e:
        return f"Erro na API Anthropic: {e}"

def extrair_texto_pdf(uploaded_pdf):
    texto_completo = ""
    try:
        with pdfplumber.open(uploaded_pdf) as pdf:
            for page in pdf.pages:
                texto_pagina = page.extract_text()
                if texto_pagina:
                    texto_completo += texto_pagina + "\n"
        return texto_completo
    except Exception as e:
        return f"Erro ao ler o PDF: {e}"

# --- INTERFACE PRINCIPAL DO STREAMLIT ---

st.title("🤖 DRX - Leitor e Validador de Bobinas")
st.markdown("---")

col1, col2 = st.columns([1, 1])

with col1:
    st.subheader("1. Upload do Manifesto (PDF)")
    uploaded_pdf = st.file_uploader("Selecione o Manifesto (.pdf)", type="pdf", key="pdf")

with col2:
    st.subheader("2. Captura da Etiqueta (Foto)")
    camera_photo = st.camera_input("Tirar foto da etiqueta", key="camera")

system_prompt_ocr = """
Analise a imagem da etiqueta de bobina fornecida. Extraia as seguintes informações e retorne-as EXATAMENTE neste formato JSON, sem texto adicional:
{
  "identificacao": "NÚMERO DA BOBINA",
  "espessura": "VALOR EM MM",
  "largura": "VALOR EM MM",
  "peso_liquido": "VALOR EM KG",
  "grau_aco": "TIPO DE AÇO",
  "colada": "CÓDIGO DO LOTE/COLADA"
}
Se algum campo não for encontrado, retorne null.
"""

texto_manifesto = ""
dados_etiqueta_json = None

if uploaded_pdf:
    with st.spinner("Lendo manifesto PDF..."):
        texto_manifesto = extrair_texto_pdf(uploaded_pdf)
    if texto_manifesto:
        with st.expander("Visualizar conteúdo do Manifesto"):
            st.text(texto_manifesto[:2000] + "...")

if camera_photo:
    with st.spinner("Analisando foto da etiqueta com IA..."):
        bytes_data = camera_photo.getvalue()
        resultado_ia = processar_com_google(bytes_data, system_prompt_ocr)

        if resultado_ia.startswith("{") and resultado_ia.endswith("}"):
            import json
            try:
                dados_etiqueta_json = json.loads(resultado_ia)
                st.success("✅ Dados da etiqueta extraídos com sucesso!")
                st.subheader("Dados da Etiqueta Lida:")
                st.json(dados_etiqueta_json)
            except json.JSONDecodeError:
                st.error(f"Erro ao decodificar JSON retornado pela IA: {resultado_ia}")
        else:
            st.error(f"IA não retornou um JSON válido. Resposta: {resultado_ia}")

# --- VALIDAÇÃO ---
if uploaded_pdf and camera_photo and dados_etiqueta_json:
    st.markdown("---")
    st.subheader("3. Validação Automática")
    
    id_etiqueta = dados_etiqueta_json.get("identificacao")
    
    if id_etiqueta and id_etiqueta in texto_manifesto:
        st.success(f"✅ A identificação da bobina **{id_etiqueta}** foi ENCONTRADA no manifesto.")
    elif id_etiqueta:
        st.error(f"❌ A identificação da bobina **{id_etiqueta}** NÃO foi localizada no manifesto.")
    else:
        st.warning("Não foi possível ler o ID da bobina na etiqueta para validação.")

st.markdown("---")
st.caption("DRX Bobinas - Sistema de Conferência Inteligente")